  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*5-t*1.5)+Math.sin(dist*0.04+ang*7-t*1.2))*0.4;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral+layerAct)*2.5);
  const g23=Math.abs(Math.sin(x*Math.PI/23))<0.018?0.15:0;
  const g19y=Math.abs(Math.sin(y*Math.PI/19))<0.018?0.15:0;
  const g57=Math.abs(Math.sin(x*Math.PI/57))<0.012?0.07:0;
  const g47y=Math.abs(Math.sin(y*Math.PI/47))<0.012?0.07:0;
  const uiGrid=g23+g19y+g57+g47y;
  const topBar=y<3?0.9:0;
  const botBar=y>236?0.7:0;
  const sideBarL=x<2?0.5:0;
  const sideBarR=x>477?0.5:0;
  const bars=topBar+botBar+sideBarL+sideBarR;
