  const tickY=Math.abs(y%23)<1&&x<6?0.4:0;
  const ticks=tickX+tickY;
  const textLine=(y>30&&y<220)?(Math.sin(x*1.7+y*0.3+t*0.2)*Math.sin(x*0.5-t*0.15)+Math.sin(x*2.3+y*0.7+t*0.3)*0.5>0.8?0.08:0):0;
  const winX=x>140&&x<340&&y>60&&y<180;
  const winBorder=winX&&(x<143||x>337||y<63||y>177)?0.6:0;
  const winTitle=winX&&y<72?0.35:0;
  const statusBar=Math.abs(y-195)<4&&x>150&&x<330?0.4+Math.sin(x*0.1+t)*0.1:0;
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const uiTotal=uiGrid+bars+ticks+textLine+winBorder+winTitle+statusBar;
  const blend=reaction*0.6+cell*0.15+uiTotal*0.25;
  const v=Math.max(0,Math.min(1,blend*0.5+0.5));
  const pal=[[2,3,18],[4,15,55],[0,60,140],[0,180,210],[0,255,170],[140,255,40],[255,200,0],[255,70,70],[255,40,160],[160,30,255],[60,0,180],[2,3,18]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const glow=Math.pow(Math.max(0,reaction),2)*2.0;
  const edge=Math.abs(reaction)>0.7?1.5:1.0;
  const lum=0.65+glow+(bars>0?0.35:0)+(winBorder>0?0.2:0);
  const saccade=1+Math.sin(t*14*0.3)*0.06;
  const fl=lum*edge*saccade;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*fl)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*fl)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*fl)|0
  ];
}
